describe('File Upload Progress Bar', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/upload');
    cy.get('[data-testid="file-input"]').as('fileInput');
    cy.get('[data-testid="upload-button"]').as('uploadButton');
  });

  it('should display progress bar while file is being uploaded', () => {
    const fileName = 'test-file.pdf';

    cy.get('@fileInput').selectFile('cypress/fixtures/test-file.pdf', { force: true });
    cy.get('@uploadButton').click();

    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow');

    cy.get('[data-testid="progress-value"]').invoke('text').then((value) => {
      const progressValue = parseInt(value);
      expect(progressValue).to.be.greaterThan(0);
      expect(progressValue).to.be.lessThanOrEqual(100);
    });

    cy.get('[data-testid="upload-success"]', { timeout: 10000 }).should('be.visible');
    cy.get('[data-testid="progress-bar"]').should('have.attr', 'aria-valuenow', '100');
  });

  it('should display individual progress bars for multiple files', () => {
    const files = ['test-file-1.pdf', 'test-file-2.pdf', 'test-file-3.pdf'];

    cy.get('@fileInput').selectFile([
      'cypress/fixtures/test-file-1.pdf',
      'cypress/fixtures/test-file-2.pdf',
      'cypress/fixtures/test-file-3.pdf'
    ], { force: true });

    cy.get('@uploadButton').click();

    cy.get('[data-testid="progress-container"]').should('have.length', 3);

    cy.get('[data-testid="progress-bar"]').each(($progressBar, index) => {
      cy.wrap($progressBar).should('be.visible');
      cy.wrap($progressBar).parent().find('[data-testid="file-name"]').should('contain', files[index]);
    });

    cy.get('[data-testid="progress-bar"]').each(($progressBar) => {
      cy.wrap($progressBar).invoke('attr', 'aria-valuenow').then((value) => {
        const progressValue = parseInt(value);
        expect(progressValue).to.be.greaterThanOrEqual(0);
        expect(progressValue).to.be.lessThanOrEqual(100);
      });
    });

    cy.get('[data-testid="upload-success"]', { timeout: 15000 }).should('be.visible');
  });

  it('should handle upload cancellation and hide progress bar', () => {
    cy.get('@fileInput').selectFile('cypress/fixtures/test-file.pdf', { force: true });
    cy.get('@uploadButton').click();

    cy.get('[data-testid="progress-bar"]').should('be.visible');
    cy.get('[data-testid="cancel-button"]').should('be.visible').click();

    cy.get('[data-testid="progress-bar"]').should('not.exist');
    cy.get('[data-testid="upload-cancelled"]').should('be.visible');
  });

  it('should show progress bar with correct percentage increments', () => {
    cy.get('@fileInput').selectFile('cypress/fixtures/large-file.pdf', { force: true });
    cy.get('@uploadButton').click();

    cy.get('[data-testid="progress-bar"]').should('be.visible');

    let previousValue = 0;
    cy.get('[data-testid="progress-value"]').invoke('text').then((value) => {
      previousValue = parseInt(value);
      expect(previousValue).to.be.greaterThanOrEqual(0);
    });

    cy.wait(500);

    cy.get('[data-testid="progress-value"]').invoke('text').then((value) => {
      const currentValue = parseInt(value);
      expect(currentValue).to.be.greaterThanOrEqual(previousValue);
    });

    cy.get('[data-testid="upload-success"]', { timeout: 15000 }).should('be.visible');
  });
});
